using System;using System.Linq;using System.Drawing;using System.Globalization;using System.Windows.Forms;
namespace Tvxd.Meps {
 public sealed class WireCatalogUi061:Form {
  WireCatalog061 data;DataGridView grid;ComboBox groups;Label status;string path,expected;public bool Saved;bool dirty;
  public WireCatalogUi061(WireCatalog061 source,string file,string original){data=source.Clone();path=file;expected=original;Text="MEPS · QUẢN LÝ DÂY DẪN";Size=new Size(900,510);MinimumSize=new Size(800,450);Font=new Font("Segoe UI",8);BackColor=Color.FromArgb(240,245,249);StartPosition=FormStartPosition.CenterParent;
   var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=42,Padding=new Padding(6)};groups=new ComboBox{Width=150,DropDownStyle=ComboBoxStyle.DropDownList};top.Controls.Add(groups);top.Controls.Add(B("+ NHÓM",()=>Group(0)));top.Controls.Add(B("ĐỔI TÊN NHÓM",()=>Group(1)));top.Controls.Add(B("XÓA NHÓM",()=>Group(2)));Controls.Add(top);
   var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=40,Padding=new Padding(6)};bottom.Controls.Add(B("+ DÂY",Add));bottom.Controls.Add(B("XÓA DÂY",()=>{if(grid.CurrentRow!=null)grid.Rows.Remove(grid.CurrentRow);}));bottom.Controls.Add(B("LƯU MẶC ĐỊNH",Save));bottom.Controls.Add(B("ĐÓNG",()=>Close()));Controls.Add(bottom);
   status=new Label{Dock=DockStyle.Bottom,Height=46,Padding=new Padding(9,2,9,0),Text="NHẤP ĐÔI Ô MÀU ĐỂ CHỌN MÀU. TÊN DÂY LÀ TÊN HIỂN THỊ; MÃ CÁP GỐC KHÔNG ĐỔI.\nCHỈ ÁP DỤNG CHO NÉT VẼ MỚI. XÓA KHỎI DANH SÁCH KHÔNG XÓA NÉT TRONG CAD."};Controls.Add(status);
   grid=new DataGridView{Name="wireCatalogGrid061",Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,BackgroundColor=Color.White,BorderStyle=BorderStyle.None,EnableHeadersVisualStyles=false,ColumnHeadersHeight=36,SelectionMode=DataGridViewSelectionMode.CellSelect};grid.DefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleCenter;grid.ColumnHeadersDefaultCellStyle.Alignment=DataGridViewContentAlignment.MiddleCenter;grid.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(223,233,241);grid.RowTemplate.Height=26;
   grid.Columns.Add(new DataGridViewComboBoxColumn{Name="group",HeaderText="NHÓM",FillWeight=100});grid.Columns.Add("name","TÊN DÂY");grid.Columns[1].FillWeight=160;grid.Columns.Add("color","MÀU");grid.Columns[2].FillWeight=75;var patterns=new DataGridViewComboBoxColumn{Name="pattern",HeaderText="KIỂU NÉT",FillWeight=100};patterns.Items.AddRange(WireCatalog061.Patterns);grid.Columns.Add(patterns);var weights=new DataGridViewComboBoxColumn{Name="weight",HeaderText="ĐỘ DÀY (MM)",FillWeight=80};weights.Items.AddRange(WireCatalog061.Weights.Select(x=>(object)(x/100m).ToString("0.00",CultureInfo.InvariantCulture)).ToArray());grid.Columns.Add(weights);grid.Columns.Add("scale","TỶ LỆ NÉT");grid.Columns[5].FillWeight=75;foreach(DataGridViewColumn c in grid.Columns)c.SortMode=DataGridViewColumnSortMode.NotSortable;
   grid.CellDoubleClick+=(s,e)=>{if(e.RowIndex<0||e.ColumnIndex!=2)return;using(var dlg=new ColorDialog()){try{dlg.Color=ColorTranslator.FromHtml(Convert.ToString(grid.Rows[e.RowIndex].Cells[2].Value));}catch{}if(dlg.ShowDialog(this)==DialogResult.OK)grid.Rows[e.RowIndex].Cells[2].Value="#"+dlg.Color.R.ToString("X2")+dlg.Color.G.ToString("X2")+dlg.Color.B.ToString("X2");}};
   grid.CellFormatting+=(s,e)=>{if(e.ColumnIndex==2&&e.Value!=null)try{var color=ColorTranslator.FromHtml(e.Value.ToString());e.CellStyle.BackColor=color;e.CellStyle.ForeColor=color.GetBrightness()<0.5?Color.White:Color.Black;}catch{}};
   grid.DataError+=(s,e)=>{e.ThrowException=false;status.Text="KIỂM TRA Ô ĐANG CHỌN.";};Controls.Add(grid);grid.BringToFront();RefreshGroups();foreach(var w in data.wires)Row(w);grid.CellValueChanged+=delegate{dirty=true;};grid.RowsRemoved+=delegate{dirty=true;};FormClosing+=delegate(object sender,FormClosingEventArgs e){grid.EndEdit();if(!dirty)return;var answer=MessageBox.Show(this,"DANH MỤC CHƯA LƯU. LƯU TRƯỚC KHI ĐÓNG?","DÂY DẪN",MessageBoxButtons.YesNoCancel);if(answer==DialogResult.Cancel){e.Cancel=true;return;}if(answer==DialogResult.Yes)try{Save();}catch(Exception ex){status.Text=ex.Message;e.Cancel=true;}};
  }
  Button B(string text,Action action){var b=new InputRoundButton055{Text=text,AutoSize=false,Width=Math.Max(75,TextRenderer.MeasureText(text,Font).Width+20),Height=27,BackColor=Color.FromArgb(24,102,119),ForeColor=Color.White,Margin=new Padding(3)};b.Click+=delegate{try{action();}catch(Exception ex){status.Text=ex.Message;status.ForeColor=Color.Firebrick;}};return b;}
  void RefreshGroups(){var selected=groups.SelectedItem as string;groups.Items.Clear();groups.Items.AddRange(data.groups.ToArray());if(groups.Items.Count>0)groups.SelectedIndex=Math.Max(0,data.groups.IndexOf(selected));var col=(DataGridViewComboBoxColumn)grid.Columns[0];col.Items.Clear();col.Items.AddRange(data.groups.ToArray());}
  void Row(WireChoice061 w){int i=grid.Rows.Add(w.group,w.name,w.color,w.pattern,(w.weight/100m).ToString("0.00",CultureInfo.InvariantCulture),w.scale.ToString(CultureInfo.InvariantCulture));grid.Rows[i].Tag=w;grid.Rows[i].Cells[1].ToolTipText=w.presetLayer==null?"DÂY TỰ TẠO: CHƯA TỰ SUY QUY CÁCH ĐIỆN TỪ TÊN.":"TÊN HIỂN THỊ; MÃ CÁP GỐC GIỮ NGUYÊN: "+w.presetLayer;}
  WireCatalog061 Read(){if(!grid.EndEdit())throw new InvalidOperationException("KẾT THÚC Ô ĐANG NHẬP.");var d=data.Clone();d.wires.Clear();foreach(DataGridViewRow r in grid.Rows){var old=(WireChoice061)r.Tag;var w=new WireChoice061{id=old.id,presetLayer=old.presetLayer,sample=old.sample,group=Convert.ToString(r.Cells[0].Value),name=Convert.ToString(r.Cells[1].Value),color=Convert.ToString(r.Cells[2].Value),pattern=Convert.ToString(r.Cells[3].Value),weight=checked((int)(Floors054.Number(Convert.ToString(r.Cells[4].Value))*100)),scale=(double)Floors054.Number(Convert.ToString(r.Cells[5].Value))};d.wires.Add(w);}d.Validate();return d;}
  void Add(){dirty=true;if(groups.SelectedItem==null)throw new InvalidOperationException("THÊM NHÓM TRƯỚC.");var w=new WireChoice061{group=groups.SelectedItem.ToString(),name=""};Row(w);grid.CurrentCell=grid.Rows[grid.Rows.Count-1].Cells[1];grid.BeginEdit(true);}
  void Group(int action){dirty=true;var chosen=groups.SelectedItem as string;if(action!=0&&chosen==null)return;if(action==2){if(grid.Rows.Cast<DataGridViewRow>().Any(r=>Convert.ToString(r.Cells[0].Value)==chosen))throw new InvalidOperationException("NHÓM CÒN DÂY. CHUYỂN DÂY SANG NHÓM KHÁC HOẶC XÓA DÂY TRƯỚC.");data.groups.Remove(chosen);data.wires.RemoveAll(w=>w.group==chosen);RefreshGroups();return;}string name=Ask(action==0?"THÊM NHÓM":"ĐỔI TÊN NHÓM",action==0?"":chosen);if(name==null)return;if(string.IsNullOrWhiteSpace(name)||name.Length>60||data.groups.Any(x=>x!=chosen&&string.Equals(x,name,StringComparison.OrdinalIgnoreCase))||(action==0&&data.groups.Any(x=>string.Equals(x,name,StringComparison.OrdinalIgnoreCase))))throw new InvalidOperationException("TÊN NHÓM RỖNG HOẶC TRÙNG.");if(action==0)data.groups.Add(name);else{data.groups[data.groups.IndexOf(chosen)]=name;((DataGridViewComboBoxColumn)grid.Columns[0]).Items.Add(name);foreach(DataGridViewRow r in grid.Rows)if(Convert.ToString(r.Cells[0].Value)==chosen)r.Cells[0].Value=name;foreach(var w in data.wires)if(w.group==chosen)w.group=name;}RefreshGroups();groups.SelectedItem=name;}
  string Ask(string title,string initial){using(var f=new Form{Text=title,ClientSize=new Size(330,110),StartPosition=FormStartPosition.CenterParent,Font=Font}){var t=new TextBox{Left=12,Top=15,Width=305,Text=initial};var ok=new Button{Text="ÁP DỤNG",Left=200,Top=60,Width=117,DialogResult=DialogResult.OK};f.Controls.AddRange(new Control[]{t,ok});f.AcceptButton=ok;return f.ShowDialog(this)==DialogResult.OK?t.Text:null;}}
  void Save(){var d=Read();WireCatalog061.Save(path,d,expected);expected=d.Encode();data=d;Saved=true;dirty=false;status.ForeColor=Color.Teal;status.Text="ĐÃ LƯU MẶC ĐỊNH. ĐÓNG BẢNG ĐỂ CHỌN DÂY VỪA SỬA.";}
 }
}
